args.sql:
SELECT a.catlabel, 
       ROUND(CAST(AVG(im.interaction_behavior->'time_spent'->>'reading_seconds') AS numeric), 4) as avg_reading_sec
FROM articles a JOIN recommendations r ON a.artkey = r.artlink JOIN interactions i ON r.reckey = i.reclink JOIN interactionmetrics im ON i.intkey = im.intmetkey GROUP BY a.catlabel ORDER BY a.catlabel;

SELECT a.catlabel, 
       ROUND(CAST(AVG((im.interaction_behavior->'time_spent'->>'reading_seconds')::numeric) AS numeric), 4) as avg_reading_sec
FROM articles a JOIN recommendations r ON a.artkey = r.artlink JOIN interactions i ON r.reckey = i.reclink JOIN interactionmetrics im ON i.intkey = im.intmetkey GROUP BY a.catlabel ORDER BY a.catlabel;
